import { prisma } from "@/lib/prisma";
import AppShell from "@/components/AppShell";
import TeacherForm from "./TeacherForm";

export default async function TeachersPage() {
  const teachers = await prisma.teacher.findMany({ orderBy: { name: "asc" } });
  return <AppShell><h1 className="title">Teachers</h1><p className="subtitle">Manage teacher and faculty records.</p>
    <div className="grid grid-2" style={{marginTop:20}}>
      <TeacherForm />
      <div className="card"><h2>Faculty</h2><div className="table-wrap"><table><thead><tr><th>Employee No.</th><th>Name</th><th>Department</th><th>Subject</th></tr></thead><tbody>
      {teachers.map(t=><tr key={t.id}><td>{t.employeeNo}</td><td>{t.name}</td><td>{t.department}</td><td>{t.subject}</td></tr>)}
      </tbody></table></div></div>
    </div>
  </AppShell>;
}
